const cats=[
 {slug:'cushion-covers',name:'Cushion Covers',short:'Cushions',heading:'Small details.\nSofter spaces.',intro:'A different texture. A warmer corner. Discover cushion covers that make a room feel more like you.',hero:'linen-vignette',editorial:'about-img-01',editorTitle:'The beauty is\nin the detail.',editorText:'A thoughtful seam, a tactile surface, a color that feels at home. Look closely at the finishing touches before choosing your cushion covers.',products:[['Linen Layers','gal-02-1','A softly textured linen-inspired palette.'],['Quiet Contrast','img-03','Pattern and plain fabric in warm, earthy tones.'],['Natural Pair','ramie-pillows','A pair of woven textures for relaxed spaces.']],size:'Cushion cover fit',measure:['Measure your insert from seam to seam, without compressing the filling.','Match the cover dimensions to the insert; confirm whether filling is included.','Choose a rectangular accent to balance square cushions.'],sizes:['40 × 40 cm','45 × 45 cm','50 × 50 cm'],care:'Close zips and turn covers inside out before washing, when the care label allows machine washing.',palette:['Oat','Clay','Olive'],theme:'cushion'},
 {slug:'throws-blankets',name:'Throws & Blankets',short:'Throws',heading:'A little warmth.\nA lot of comfort.',intro:'Loose knits, generous folds and soft, quiet color. Make space for slower mornings and evenings at home.',hero:'ramie-throw',editorial:'blog-02',editorTitle:'Texture you\ncan almost feel.',editorText:'From an open weave to a closer knit, structure changes the way a throw falls. Consider warmth, weight and everyday use together.',products:[['Softly Woven','hay-blanket','An inviting layer for a chair or reading corner.'],['Cotton Companion','cotton-throw-set','Soft neutral layers with a tactile weave.'],['The Weekend Layer','img-02','A gentle mix of ribbed and smooth textures.']],size:'Find your perfect drape',measure:['For a sofa throw, measure the area you want to cover.','For a bed blanket, add your preferred drop to both sides.','Check the fabric weight and composition before choosing.'],sizes:['130 × 170 cm','150 × 200 cm','200 × 220 cm'],care:'Air throws regularly. Follow the individual label for washing, drying and wool care.',palette:['Cream','Sand','Cocoa'],theme:'throw'},
 {slug:'tablecloths',name:'Tablecloths',short:'Tablecloths',heading:'Every table.\nAn occasion.',intro:'Relaxed linen textures and beautifully simple tablecloths for breakfast, long lunches and everything in between.',hero:'rust-runner',editorial:'blog-12',editorTitle:'Set a beautiful\neveryday table.',editorText:'Let the tablecloth set the mood. A soft neutral makes room for seasonal flowers, handmade ceramics and the people around your table.',products:[['Sunday Table','silk-cushion','Natural tones and an easy, generous drape.'],['Light & Linen','scandi-dining','An airy palette for daylight dining.'],['Ivory & Natural','linen-table-setting','Warm layers for a welcoming table.']],size:'A considered table drop',measure:['Measure the length and width of the tabletop.','Add twice your preferred drop to each measurement.','For round tables, add twice the drop to the diameter.'],sizes:['20 cm casual drop','30 cm generous drop','Measure before ordering'],care:'Treat spills promptly and gently. Avoid rubbing stains into the fibers; follow the care label.',palette:['Chalk','Flax','Terracotta'],theme:'table'},
 {slug:'table-runners',name:'Table Runners',short:'Runners',heading:'A line of\nquiet character.',intro:'A little fabric changes the whole setting. Explore layers that bring rhythm, texture and a touch of color to your table.',hero:'ivory-runner',editorial:'scissors',editorTitle:'Room for\nthe little things.',editorText:'Keep beautiful wood in view, frame a favorite vase or layer a runner over a tablecloth. Small gestures make a setting feel considered.',products:[['Natural Rhythm','highland-runner','An understated woven accent.'],['Curved Lines','beige-table-runner','A soft geometric statement in neutral shades.'],['Fringed Finish','fringe-runner','A simple, tactile finishing touch.']],size:'Length makes the difference',measure:['Measure the table along its longest side.','Add a drop at each end if you want an overhanging runner.','Keep the width narrow enough to leave room for place settings.'],sizes:['Short centerpiece','Full table length','With an end drop'],care:'Smooth into shape after cleaning. Protect delicate fringe and embroidery according to the label.',palette:['Ivory','Taupe','Walnut'],theme:'runner'},
 {slug:'living-room',name:'Living Room',short:'Living Room',heading:'Make yourself\nat home.',intro:'Pair tactile cushions with an inviting throw. Bring a room together through the small things you reach for every day.',hero:'wabi-living',editorial:'numbers-img',editorTitle:'A room that\nfeels like you.',editorText:'Begin with the colors you already love. Layer a small-scale pattern, a plain weave and a softer knit to add depth without clutter.',products:[['Soft Neutrals','neutral-pillows','A quiet balance of ivory and warm grey.'],['Natural Ease','linen-sofa','Simple silhouettes and warm textile layers.'],['Warm Minimalism','stripe-living','Comfortable textures in a light-filled space.']],size:'Balance your layers',measure:['Start with the size of your sofa or armchair.','Mix two cushion scales to give the arrangement depth.','Leave a clear place to sit; comfort comes first.'],sizes:['One chair','A two-seat sofa','A larger corner'],care:'Rotate cushions and throws, protect them from long exposure to direct sunlight and follow each care label.',palette:['Oatmeal','Stone','Moss'],theme:'room'},
 {slug:'dining-room',name:'Dining Room',short:'Dining Room',heading:'Gather around\nsomething lovely.',intro:'Thoughtful table linens, warm colors and tactile details. Create a table that welcomes everyday moments and special guests.',hero:'slow-dining',editorial:'service-03-1',editorTitle:'A more personal\nplace setting.',editorText:'Build a setting in layers: a gentle base, a contrasting runner and one natural detail. Keep the palette simple and let texture do the talking.',products:[['Woven Together','woven-runner','Texture that connects wood and soft upholstery.'],['A Quiet Corner','summer-linen','Relaxed linen and understated accessories.'],['Warm Gatherings','dining-detail','A soft table setting with warm, natural contrast.']],size:'Plan your place settings',measure:['Leave enough room for each guest and their place setting.','Choose a runner width that works with your plates.','Keep centerpieces low enough for easy conversation.'],sizes:['Everyday dining','A shared gathering','A special setting'],care:'Read each textile label separately when washing coordinated sets; similar colors may need different care.',palette:['Natural','Sage','Cinnamon'],theme:'dining'}
];
const page=location.pathname.split('/').pop().replace('.html','')||'index';
const cat=cats.find(c=>c.slug===page);
document.title=page==='index'?C.title:`${C.pageTitles?.[page]||cat?.name||({'privacy':'Privacy Policy','terms':'Terms & Conditions','cookies':'Cookie Policy','shipping-returns':'Shipping & Returns','materials-care':'Materials & Care'}[page]||'Home')} | ${C.name}`;
document.querySelector('link[rel=icon]').href=C.favicon;
const brand=`<a class="brand" href="index.html" aria-label="${esc(C.name)} home"><img src="${esc(C.logo)}" alt="" width="36" height="36"><span>${esc(C.name)}</span></a>`;
document.querySelector('#header').innerHTML=`<div class="container header-inner">${brand}<nav aria-label="Main navigation" id="navigation">${C.navigation.map((n,i)=>i===0?`<div class="collection-dropdown"><button class="collection-toggle nav-link" aria-expanded="false" aria-controls="collection-menu">${esc(n.label)}<svg viewBox="0 0 12 8" aria-hidden="true"><path d="m1 1 5 5 5-5"/></svg></button><div class="collection-menu" id="collection-menu"><div class="dropdown-intro"><span class="script">Find your feeling</span><strong>A little texture.<br>A whole lot of home.</strong><a href="index.html#collections">Explore all collections</a></div><div class="dropdown-links">${cats.map((c,j)=>`<a href="${c.slug}.html"><span class="dropdown-symbol symbol-${j}" aria-hidden="true">${['▧','≋','▱','⌇','⌂','✳'][j]}</span><span>${c.name}<small>${['Soft details, beautiful textures','Your everyday layer of comfort','Set the mood for every meal','A thoughtful finishing touch','Make yourself at home','Make room for together'][j]}</small></span></a>`).join('')}</div></div></div>`:a(n.href,esc(n.label),'nav-link')).join('')}<div class="mobile-categories">${cats.map(c=>a(c.slug+'.html',c.name,'')).join('')}</div></nav><div class="header-actions"><button class="search-open" aria-label="Search website"><svg viewBox="0 0 24 24" fill="none"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg></button><a class="header-cta" href="index.html#contact">Let’s talk</a><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="navigation"><span></span><span></span></button></div></div>`;
const section=(id,cls,html)=>`<section id="${id}" class="section ${cls}"><div class="container">${html}</div></section>`;
const title=(h,p='',center=false,animated=true)=>`<div class="section-heading ${center?'center':''}"${animated?' data-reveal':''}><h2>${h}</h2>${p?`<p>${p}</p>`:''}</div>`;
const accordion=(items)=>`<div class="accordion">${items.map(([q,v],i)=>`<div class="accordion-item"><h3><button class="accordion-trigger" aria-expanded="false" aria-controls="answer-${page}-${i}">${q}<span class="plus"></span></button></h3><div class="accordion-content" id="answer-${page}-${i}" inert><div><p>${v}</p></div></div></div>`).join('')}</div>`;
const marquee=(words)=>`<div class="marquee" aria-label="${words.join(', ')}"><div aria-hidden="true">${[0,1,2,3].map(()=>words.map(w=>`<span>${w}</span><b>✳</b>`).join('')).join('')}</div></div>`;
const carousel=(slides,cls='')=>`<div class="carousel ${cls}" data-reveal><div class="swiper"><div class="swiper-wrapper">${slides.map(s=>`<div class="swiper-slide">${s}</div>`).join('')}</div></div><div class="carousel-bottom"><div class="swiper-pagination"></div><div class="slider-controls"><button class="prev" aria-label="Previous slide">←</button><button class="next" aria-label="Next slide">→</button></div></div></div>`;
const contactForm=()=>`<form class="contact-form" action="${esc(C.form.endpoint)}" method="post"><div class="form-row"><label>Your name<input name="name" autocomplete="name" placeholder="Full name" minlength="2" maxlength="100" required></label><label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required></label></div><label>I’m interested in<select name="service" required><option value="">Select a topic</option>${(C.form.topics||cats.map(c=>c.name)).map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label>Your message<textarea name="message" placeholder="Tell us what you have in mind…" minlength="10" maxlength="5000" rows="3" required></textarea></label><div class="honey" aria-hidden="true"><label>Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="check"><input type="checkbox" name="consent" value="yes" required><span>I have read the <a href="privacy.html">Privacy Policy</a> and agree to be contacted about my request.</span></label><div class="form-submit"><button class="button" type="submit">${esc(C.form.submitLabel||'Send your request')}</button><span>Thoughtful questions.<br>Personal replies.</span></div><p class="form-status" role="status" aria-live="polite"></p></form>`;
const swatches=()=>`<div class="swatch-row">${['Ivory Knit','Soft Jacquard','Cotton Weave','Fine Twill','Quilted Cotton','Cocoa Wool'].map((s,i)=>`<button class="swatch" data-material="${i}" aria-label="Read about ${s}">${img('fab-0'+(i+1),s)}<span>${s}</span></button>`).join('')}</div><p class="swatch-info" aria-live="polite">Select a texture to discover what makes it different.</p>`;
const matData=[['Linen','Light, relaxed and naturally textured.','A crisp, airy look with characteristic slubs and a softly rumpled finish. Well suited to relaxed table settings and layered interiors.','Airy drape','Distinct texture','Follow the product label'],['Cotton','Soft, familiar and endlessly versatile.','A versatile starting point for everyday textiles. Different weaves create everything from smooth table linens to richly textured cushions.','Everyday comfort','Many weave options','Check washing temperature'],['Wool','A little warmth goes a long way.','A naturally warm feel with depth and softness. Consider the fiber blend, weight and care requirements when choosing your throw.','Warm handle','Soft layering','Gentle care matters']];
