 {title:'WARM LIGHT.<br>QUIET MOMENTS.',note:'The slow living edit',text:'Beautiful fabrics, considered corners and the warmest welcome home.',cta:'Explore living room',href:'living-room.html',image:'decor-lamp',alt:'Olive ceramic lamp with a pleated linen shade',label:'A softer glow',detail:'Pleated linen · Olive ceramic',tone:'olive'},
 {title:'SMALL DETAILS.<br>LOVELY RITUALS.',note:'The gathering edit',text:'Set the table. Light a candle. Make the everyday feel a little more special.',cta:'Explore dining room',href:'dining-room.html',image:'decor-candles',alt:'Ivory candles on a sculptural ceramic tray',label:'Stay a little longer',detail:'Warm ivory · Natural forms',tone:'cream'}
