 const base={effect:reduced?'fade':'cube',fadeEffect:{crossFade:true},cubeEffect:{shadow:false,slideShadows:false},loop:true,speed:reduced?0:1100,grabCursor:true,slidesPerView:1,spaceBetween:0,resizeObserver:true,a11y:{enabled:true},keyboard:{enabled:false}};
